import { useEffect, useRef, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

export default function LoginSuccess() {
  const navigate = useNavigate();
  const hasVerified = useRef(false);
  const [verificationStatus, setVerificationStatus] = useState("verifying"); // verifying, success, error
  const [errorMessage, setErrorMessage] = useState("");

  useEffect(() => {
    // Prevent multiple verifications
    if (hasVerified.current) return;
    
    const verifyToken = async () => {
      const token = new URLSearchParams(window.location.search).get("token");

      if (!token) {
        setVerificationStatus("error");
        setErrorMessage("Invalid magic link. Please request a new one.");
        setTimeout(() => {
          navigate("/?error=invalid_link", { replace: true });
        }, 2000);
        return;
      }

      try {
        hasVerified.current = true;
        setVerificationStatus("verifying");
        
        const res = await axios.get(`http://localhost:3597/api/user/verify?token=${token}`);
        
        // Store token and redirect immediately
        localStorage.setItem("authToken", res.data.token);
        setVerificationStatus("success");
        
        // Redirect to dashboard
        setTimeout(() => {
          navigate("/dashboard", { replace: true });
        }, 500);
        
      } catch (error) {
        console.error("Verification error:", error);
        setVerificationStatus("error");
        
        // Check if it's a token expiration error
        if (error.response?.data?.message?.includes("expired") || 
            error.response?.data?.message?.includes("Token expired")) {
          setErrorMessage("Your magic link has expired (valid for only 1 minute). Please request a new one.");
          setTimeout(() => {
            navigate("/?error=expired_link", { replace: true });
          }, 2000);
        } else {
          setErrorMessage(error.response?.data?.message || "Invalid magic link. Please request a new one.");
          setTimeout(() => {
            navigate("/?error=invalid_link", { replace: true });
          }, 2000);
        }
      }
    };

    verifyToken();
  }, [navigate]);

  return (
    <div className="min-h-screen flex items-center justify-center" style={{ background: 'linear-gradient(135deg, #0a0f1e 0%, #1a1f35 100%)' }}>
      <div className="text-center max-w-md px-4">
        {verificationStatus === "verifying" && (
          <>
            <div className="w-20 h-20 mx-auto mb-6 rounded-full bg-indigo-500/20 flex items-center justify-center animate-pulse-glow">
              <div className="w-10 h-10 border-4 border-indigo-400 border-t-transparent rounded-full animate-spin"></div>
            </div>
            <h2 className="text-2xl font-semibold text-white mb-2">Verifying your magic link...</h2>
            <p className="text-gray-400">Please wait while we securely log you in</p>
            <p className="text-gray-500 text-sm mt-4">This will only take a moment</p>
          </>
        )}

        {verificationStatus === "success" && (
          <>
            <div className="w-20 h-20 mx-auto mb-6 rounded-full bg-green-500/20 flex items-center justify-center animate-pulse-glow">
              <svg className="w-10 h-10 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <h2 className="text-2xl font-semibold text-white mb-2">Login Successful!</h2>
            <p className="text-gray-400">Redirecting you to dashboard...</p>
          </>
        )}

        {verificationStatus === "error" && (
          <>
            <div className="w-20 h-20 mx-auto mb-6 rounded-full bg-red-500/20 flex items-center justify-center animate-pulse-glow">
              <svg className="w-10 h-10 text-red-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <h2 className="text-2xl font-semibold text-white mb-2">Link Expired or Invalid</h2>
            <p className="text-red-400 mb-4">{errorMessage}</p>
            <p className="text-gray-400">Redirecting you to login page...</p>
            <button
              onClick={() => navigate("/")}
              className="mt-6 bg-indigo-500 hover:bg-indigo-600 text-white px-6 py-2 rounded-lg transition-colors"
            >
              Go to Login
            </button>
          </>
        )}
      </div>
    </div>
  );
}
